<form method="get" class="filtros"><label>Buscar por nombre o código<input name="q" value="<?= e($q) ?>" maxlength="150"></label><label>Categoría<select name="categoria"><option value="0">Todas</option><?php foreach ($listaCategorias as $c): ?><option value="<?= e($c['id']) ?>" <?= $cat===$c['id']?'selected':'' ?>><?= e($c['nombre']) ?></option><?php endforeach ?></select></label><label>Orden<?php if ($cursor): ?><input type="hidden" name="modo" value="cursor"><select disabled><option>ID ascendente (por clave)</option></select><?php else: ?><select name="orden"><?php foreach (App\ProductoRepositorio::ORDENES as $clave=>$nombre): ?><option value="<?= e($clave) ?>" <?= $clave===$orden?'selected':'' ?>><?= e($nombre) ?></option><?php endforeach ?></select><?php endif ?></label><button>Aplicar</button></form>
<?php if ($q!==''): ?><p>Resultados para «<?= e($q) ?>»</p><?php endif ?>
<?php if ($cursor): ?><p class="resumen">Modo por clave ID · <?= count($filas) ?> productos en este bloque · sin COUNT ni OFFSET</p><?php else: ?><p class="resumen"><?= e($pagina->rango()) ?></p><?php endif ?>
<div class="tabla"><table><thead><tr><th>Código</th><th>Producto</th><th>Categoría</th><th>Precio</th><th>Stock</th><th>Socio</th><th>Acciones</th></tr></thead><tbody>
<?php foreach ($filas as $p): ?><tr><td><?= e($p['codigo']) ?></td><td><?= e($p['nombre']) ?></td><td><?= e($p['categoria']) ?></td><td class="numero"><?= e(bs($p['precio'])) ?></td><td class="numero"><?= e($p['stock']) ?></td><td><a href="/socios/<?= e($p['socio_id']) ?>"><?= e($p['socio']) ?></a></td><td class="acciones"><a href="/productos/<?= e(rawurlencode($p['codigo'])) ?>/editar">Editar</a><form action="/productos/<?= e(rawurlencode($p['codigo'])) ?>/eliminar" method="post"><?= token() ?><button class="borrar">Eliminar</button></form></td></tr><?php endforeach ?>
<?php if (!$filas): ?><tr><td colspan="7">No se encontraron productos.</td></tr><?php endif ?></tbody></table></div>
<?php $params=['q'=>$q,'categoria'=>$cat,'orden'=>$orden]; if (!$cursor): require __DIR__.'/paginacion.php'; endif ?>
<p><?php if ($cursor): ?><?php if ($hayMas): ?><a class="boton" href="<?= e(url('/productos',['modo'=>'cursor','despues'=>end($filas)['id'],'q'=>$q,'categoria'=>$cat])) ?>">Siguiente bloque por clave</a><?php endif ?> <a href="/productos">Volver al listado numerado</a><?php else: ?><a href="<?= e(url('/productos',['modo'=>'cursor','q'=>$q,'categoria'=>$cat])) ?>">Ver paginación por clave ID</a> <small>(orden fijo por ID, sin total)</small><?php endif ?></p>
